const L = params.length;
const W = L * 0.255;
const T = L * 0.034;
const baseY = L * 0.055;
const boardShape = [
  [0, L],
  [W * 0.28, L * 0.965],
  [W * 0.43, L * 0.88],
  [W * 0.5, L * 0.68],
  [W * 0.48, L * 0.38],
  [W * 0.38, L * 0.12],
  [W * 0.22, 0],
  [-W * 0.22, 0],
  [-W * 0.38, L * 0.12],
  [-W * 0.48, L * 0.38],
  [-W * 0.5, L * 0.68],
  [-W * 0.43, L * 0.88],
  [-W * 0.28, L * 0.965]
];
const boardMat = { preset: 'plastic', color: params.color, roughness: 0.28 };
const stripeMat = { preset: 'plastic', color: params.stripeColor, roughness: 0.25 };
const darkMat = { preset: 'rubber', color: '#25343a', roughness: 0.65 };
const sandMat = { preset: 'sand', color: '#d8bc7a', roughness: 0.95, flatShading: true };
api.add(api.extrude(boardShape, T).translate(0, baseY, 0), boardMat);
const SW = W * 0.18;
const stripeShape = [
  [-SW * 0.42, L * 0.035],
  [SW * 0.42, L * 0.035],
  [SW * 0.5, L * 0.88],
  [SW * 0.34, L * 0.955],
  [0, L * 0.988],
  [-SW * 0.34, L * 0.955],
  [-SW * 0.5, L * 0.88]
];
api.add(api.extrude(stripeShape, T * 1.08).translate(0, baseY, 0), stripeMat);
const rail = api.tube([[-W * 0.31, baseY + L * 0.075, T * 0.52],[-W * 0.47, baseY + L * 0.35, T * 0.52],[-W * 0.49, baseY + L * 0.67, T * 0.52],[-W * 0.35, baseY + L * 0.91, T * 0.52],[0, baseY + L * 0.997, T * 0.52],[W * 0.35, baseY + L * 0.91, T * 0.52],[W * 0.49, baseY + L * 0.67, T * 0.52],[W * 0.47, baseY + L * 0.35, T * 0.52],[W * 0.31, baseY + L * 0.075, T * 0.52]], T * 0.065, 5);
api.add(rail, { preset: 'plastic', color: api.mix(params.color, '#ffffff', 0.32), roughness: 0.3 });
const finShape = [[0, 0], [L * 0.135, L * 0.035], [L * 0.105, L * 0.16], [L * 0.025, L * 0.255]];
api.add(api.extrude(finShape, T * 0.46).rotate(0, 90, 0).translate(0, baseY + L * 0.055, -T * 0.38), { preset: 'plastic', color: api.mix(params.color, '#17343b', 0.35), roughness: 0.34 });
api.add(api.cylinder(T * 0.15, T * 0.15, T * 0.3, 10).rotate(90, 0, 0).translate(W * 0.16, baseY + L * 0.12, T * 0.62), darkMat);
const sand = api.icosphereRock(L * 0.25, 0.18).scale(1.65, 0.25, 1.15).translate(0, L * 0.018, 0);
sand.vertexColor((x, y, z) => api.mix('#c9a966', '#ead497', 0.45 + 0.25 * api.noise3(x * 7, y * 7, z * 7)));
api.add(sand, sandMat);
for (let i = 0; i < 3; i++) {
  const rr = L * (0.105 + i * 0.043);
  api.add(api.torus(rr, L * 0.006).rotate(90, 0, 0).scale(1, 1, 0.7).translate(L * 0.11, L * (0.045 + i * 0.002), L * 0.035), sandMat);
}
api.collider({ kind: 'box', halfExtents: [W * 0.48, L * 0.5, T * 0.6], offset: [0, baseY + L * 0.5, 0] });
api.collider({ kind: 'box', halfExtents: [L * 0.41, L * 0.055, L * 0.29], offset: [0, L * 0.04, 0] });
return api.build();
